function lengthOfLIS(nums) {
  const n = nums.length;
  const dp = new Array(n).fill(1); // dp[i] = longest increasing subsequence ENDING at i
  let best = 1;
  for (let i = 1; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (nums[j] < nums[i]) {
        dp[i] = Math.max(dp[i], dp[j] + 1); // append nums[i] after nums[j]
      }
    }
    best = Math.max(best, dp[i]); // the LIS can end anywhere
  }
  return best;
}

