function uniquePaths(m, n) {
  // dp[r][c] = number of paths from the top-left cell to (r, c)
  const dp = Array.from({ length: m }, () => new Array(n).fill(1)); // row 0 and col 0 = 1
  for (let r = 1; r < m; r++) {
    for (let c = 1; c < n; c++) {
      dp[r][c] = dp[r - 1][c] + dp[r][c - 1]; // arrive from above or from the left
    }
  }
  return dp[m - 1][n - 1];
}

