function canPartition(nums) {
  const total = nums.reduce((a, b) => a + b, 0);
  if (total % 2 !== 0) return false; // an odd total cannot split evenly
  const target = total / 2;
  const dp = new Array(target + 1).fill(false); // dp[s]: some subset sums to s
  dp[0] = true; // the empty subset
  for (const num of nums) {
    for (let s = target; s >= num; s--) { // go DOWN so num is used at most once
      if (dp[s - num]) dp[s] = true;
    }
    if (dp[target]) return true; // early exit
  }
  return false;
}

public boolean canPartition(int[] nums) {
    int total = 0;
    for (int x : nums) total += x;
    if (total % 2 != 0) return false; // an odd total cannot split evenly
    int target = total / 2;
    boolean[] dp = new boolean[target + 1]; // dp[s]: some subset sums to s
    dp[0] = true; // the empty subset
    for (int num : nums) {
        for (int s = target; s >= num; s--) { // go DOWN: num used at most once
            if (dp[s - num]) dp[s] = true;
        }
        if (dp[target]) return true; // early exit
    }
    return false;
}

