public int rob(int[] nums) {
    int n = nums.length;
    if (n == 1) return nums[0]; // a single house has no neighbour
    // houses 0 and n - 1 are neighbours, so the best plan skips at least one of them
    return Math.max(robLine(nums, 0, n - 2), robLine(nums, 1, n - 1));
}

private int robLine(int[] nums, int lo, int hi) {
    int prev2 = 0; // best total up to house i - 2
    int prev1 = 0; // best total up to house i - 1
    for (int i = lo; i <= hi; i++) {
        int cur = Math.max(prev1, prev2 + nums[i]); // skip house i, or rob it
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

function longestPalindrome(s) {
  let start = 0, maxLen = 1; // best palindrome so far is s.slice(start, start + maxLen)
  for (let i = 0; i < s.length; i++) {
    // k = 0: odd length (centre s[i]); k = 1: even length (centre between s[i] and s[i + 1])
    for (let k = 0; k <= 1; k++) {
      let l = i, r = i + k;
      while (l >= 0 && r < s.length && s[l] === s[r]) {
        l--; // both ends match: grow the palindrome outward
        r++;
      }
      const len = r - l - 1; // the loop overshot by one on each side: palindrome is s[l + 1 .. r - 1]
      if (len > maxLen) {
        start = l + 1;
        maxLen = len;
      }
    }
  }
  return s.slice(start, start + maxLen);
}

def longest_palindrome(s):
    start, max_len = 0, 1  # best palindrome so far is s[start:start + max_len]
    for i in range(len(s)):
        # k = 0: odd length (centre s[i]); k = 1: even length (centre between s[i] and s[i + 1])
        for k in range(2):
            l, r = i, i + k
            while l >= 0 and r < len(s) and s[l] == s[r]:
                l -= 1  # both ends match: grow the palindrome outward
                r += 1
            length = r - l - 1  # the loop overshot by one on each side: palindrome is s[l + 1 .. r - 1]
            if length > max_len:
                start, max_len = l + 1, length
    return s[start:start + max_len]

public String longestPalindrome(String s) {
    int start = 0, maxLen = 1; // best palindrome so far is s.substring(start, start + maxLen)
    for (int i = 0; i < s.length(); i++) {
        // k = 0: odd length (centre s[i]); k = 1: even length (centre between s[i] and s[i + 1])
        for (int k = 0; k <= 1; k++) {
            int l = i, r = i + k;
            while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
                l--; // both ends match: grow the palindrome outward
                r++;
            }
            int len = r - l - 1; // the loop overshot by one on each side: palindrome is s[l + 1 .. r - 1]
            if (len > maxLen) {
                start = l + 1;
                maxLen = len;
            }
        }
    }
    return s.substring(start, start + maxLen);
}

function countSubstrings(s) {
  let count = 0;
  for (let i = 0; i < s.length; i++) {
    // k = 0: odd lengths (centre s[i]); k = 1: even lengths (centre between s[i] and s[i + 1])
    for (let k = 0; k <= 1; k++) {
      let l = i, r = i + k;
      while (l >= 0 && r < s.length && s[l] === s[r]) {
        count++; // s[l..r] is a palindrome
        l--; // grow outward by one letter on each side
        r++;
      }
    }
  }
  return count;
}

