function numDecodings(s) {
  const n = s.length;
  // dp[i] = number of ways to decode the first i digits, s[0..i)
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1; // empty prefix: one way (decode nothing)
  for (let i = 1; i <= n; i++) {
    if (s[i - 1] !== '0') {
      dp[i] += dp[i - 1]; // last digit alone is a letter: '1'..'9'
    }
    if (i >= 2) {
      const two = Number(s.slice(i - 2, i)); // last two digits as a number
      if (two >= 10 && two <= 26) {
        dp[i] += dp[i - 2]; // last two digits form a letter: '10'..'26'
      }
    }
  }
  return dp[n];
}

def num_decodings(s):
    n = len(s)
    # dp[i] = number of ways to decode the first i digits, s[0:i]
    dp = [0] * (n + 1)
    dp[0] = 1  # empty prefix: one way (decode nothing)
    for i in range(1, n + 1):
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]  # last digit alone is a letter: '1'..'9'
        if i >= 2:
            two = int(s[i - 2:i])  # last two digits as a number
            if 10 <= two <= 26:
                dp[i] += dp[i - 2]  # last two digits form a letter: '10'..'26'
    return dp[n]

public int numDecodings(String s) {
    int n = s.length();
    // dp[i] = number of ways to decode the first i digits, s[0..i)
    int[] dp = new int[n + 1];
    dp[0] = 1; // empty prefix: one way (decode nothing)
    for (int i = 1; i <= n; i++) {
        if (s.charAt(i - 1) != '0') {
            dp[i] += dp[i - 1]; // last digit alone is a letter: '1'..'9'
        }
        if (i >= 2) {
            int two = (s.charAt(i - 2) - '0') * 10 + (s.charAt(i - 1) - '0'); // last two digits as a number
            if (two >= 10 && two <= 26) {
                dp[i] += dp[i - 2]; // last two digits form a letter: '10'..'26'
            }
        }
    }
    return dp[n];
}

function maxProduct(nums) {
  let curMax = nums[0]; // largest product of a subarray ending at the current index
  let curMin = nums[0]; // smallest (most negative) product of a subarray ending here
  let best = nums[0];
  for (let i = 1; i < nums.length; i++) {
    const x = nums[i];
    const a = curMax * x, b = curMin * x; // use the OLD values for both updates
    // start fresh at x, or extend the largest, or extend the smallest (a negative x flips it)
    curMax = Math.max(x, a, b);
    curMin = Math.min(x, a, b);
    best = Math.max(best, curMax);
  }
  return best;
}

public int maxProduct(int[] nums) {
    int curMax = nums[0]; // largest product of a subarray ending at the current index
    int curMin = nums[0]; // smallest (most negative) product of a subarray ending here
    int best = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int x = nums[i];
        int a = curMax * x, b = curMin * x; // use the OLD values for both updates
        // start fresh at x, or extend the largest, or extend the smallest (a negative x flips it)
        curMax = Math.max(x, Math.max(a, b));
        curMin = Math.min(x, Math.min(a, b));
        best = Math.max(best, curMax);
    }
    return best;
}

function f(n, memo = {}) {
  if (n <= 2) return 1;
  if (memo[n]) return memo[n];
  return (memo[n] = f(n - 1, memo) + f(n - 2, memo));
}
